import{_ as n,o as a,c as s,a6 as e}from"./chunks/framework.B_q3ZJNF.js";const u=JSON.parse('{"title":"mini-nginx vs 真实 Nginx：差异地图与 502/504 排障手册","description":"","frontmatter":{"title":"mini-nginx vs 真实 Nginx：差异地图与 502/504 排障手册"},"headers":[],"relativePath":"nginx-course/12-troubleshooting-map.md","filePath":"nginx-course/docs/12-troubleshooting-map.md"}'),d={name:"nginx-course/12-troubleshooting-map.md"};function o(p,t,r,i,l,c){return a(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="mini-nginx-vs-真实-nginx-差异地图与-502-504-排障手册" tabindex="-1">mini-nginx vs 真实 Nginx：差异地图与 502/504 排障手册 <a class="header-anchor" href="#mini-nginx-vs-真实-nginx-差异地图与-502-504-排障手册" aria-label="Permalink to &quot;mini-nginx vs 真实 Nginx：差异地图与 502/504 排障手册&quot;">​</a></h1><p>周五晚八点，订单接口开始批量报 502。工单在三个群里流转：前端说页面报错但请求参数正常，后端说服务进程活着、日志没有异常，运维说 Nginx 机器 CPU 内存都正常。两个小时后有人翻了 Nginx 的 error.log，才看到每分钟几十条 <code>connect() failed (111: Connection refused) while connecting to upstream</code>——后端实例 OOM 被系统杀了又拉起，拉起的三分钟里实例端口根本没人监听。三个团队都没做错什么，缺的只是同一张地图：<strong>502 的现场证据在哪、由谁读</strong>。</p><p>终章做两件事收束全书：先把 mini-nginx 与真实 Nginx 的差异摆成一张地图——你需要知道手里这 600 行和线上那个工业软件之间隔着什么；再给 502/504 一份从日志出发的排障决策树——这是全书知识在事故场景里的合体调用。</p><h2 id="差异地图-你写了什么-没写什么" tabindex="-1">差异地图：你写了什么，没写什么 <a class="header-anchor" href="#差异地图-你写了什么-没写什么" aria-label="Permalink to &quot;差异地图：你写了什么，没写什么&quot;">​</a></h2><p>十二条差异按「教学保真 / 语义近似 / 未实现」分档。前两档是刻意为之的蒸馏，第三档是生产与玩具的真正距离：</p><table tabindex="0"><thead><tr><th>#</th><th>维度</th><th>mini-nginx</th><th>真实 Nginx</th><th>档位</th></tr></thead><tbody><tr><td>1</td><td>进程模型</td><td>单进程</td><td>master + N worker，<code>nginx -s reload</code> 平滑重载</td><td>未实现</td></tr><tr><td>2</td><td>事件模型</td><td>Node 事件循环</td><td>C 手写 epoll + 非阻塞 I/O（思想同构，实现层级不同）</td><td>教学保真</td></tr><tr><td>3</td><td>location 匹配</td><td>五步算法逐条对齐</td><td>一致（正则块下 proxy_pass 不做前缀替换，<code>src/proxy.ts</code> 里注明了这条对齐方式）</td><td>教学保真</td></tr><tr><td>4</td><td>try_files / 内部重定向</td><td>10 次上限 + 500</td><td>一致</td><td>教学保真</td></tr><tr><td>5</td><td>X-Forwarded-For / Host</td><td>链式追加 / <code>$proxy_host</code> 默认</td><td>一致</td><td>教学保真</td></tr><tr><td>6</td><td>WebSocket 升级</td><td>代理块自动透传 Upgrade</td><td>需显式 <code>proxy_set_header Upgrade ...</code>（严格遵守逐跳头不转发）</td><td>语义近似</td></tr><tr><td>7</td><td>负载均衡</td><td>权重展开序列 <code>[a,a,b]</code></td><td>平滑加权轮询（把权重摊开成 <code>a,b,a</code>，避免连续打同一台）</td><td>语义近似</td></tr><tr><td>8</td><td>代理缓冲</td><td>双向 pipe 直通</td><td><code>proxy_buffering on</code>：先收完上游响应再发给客户端，慢客户端拖不垮上游</td><td>语义近似</td></tr><tr><td>9</td><td>失败重试的请求体</td><td>直通管道，POST 中途失败难以安全换台重试</td><td>默认缓冲请求体，连接失败可整包重发</td><td>语义近似</td></tr><tr><td>10</td><td>gzip × ETag</td><td>压缩时仍输出强 ETag</td><td>压缩响应用弱验证 <code>W/&quot;...&quot;</code>（同一资源两种表示，强验证不成立）</td><td>语义近似</td></tr><tr><td>11</td><td>add_header 生效范围</td><td>所有响应</td><td>默认仅 2xx/3xx 部分状态码，<code>always</code> 才覆盖 4xx/5xx</td><td>语义近似</td></tr><tr><td>12</td><td>HTTP/2、sendfile、open_file_cache、access_log、多 server（server_name）</td><td>—</td><td>全部在线上服役</td><td>未实现</td></tr></tbody></table><p>读这张表的正确姿势：<strong>档位说明差距的性质</strong>。「教学保真」的五条，你写下的逻辑与 Nginx 的行为可以互为答案；「语义近似」的六条，比例与方向一致、边角不同——正是第 8 章 fetch 透明解压、本章排障这类&quot;边角&quot;事故的高发区；「未实现」的两条，是性能与运维能力的护城河，也是「能重实现核心」与「能替代生产软件」之间的诚实分界。全书 642 行 src 配 55 个测试，换来的是前十行的完整理解——这笔交易是值得的。</p><h2 id="_502-504-排障-证据在日志里-不在猜测里" tabindex="-1">502/504 排障：证据在日志里，不在猜测里 <a class="header-anchor" href="#_502-504-排障-证据在日志里-不在猜测里" aria-label="Permalink to &quot;502/504 排障：证据在日志里，不在猜测里&quot;">​</a></h2><p>排障的第一原则：502 和 504 都是<strong>网关在报上游的错</strong>——请求到了网关，网关去敲上游的门，出了事。所以证据的第一现场是网关日志，第一嫌疑人是上游，第一句该问的话是「上游那一刻到底在不在」。</p><p>真实 Nginx 的 access_log 加上上游字段后长这样（<code>log_format</code> 里配 <code>$upstream_addr/$upstream_status/$upstream_response_time</code>）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10.2.3.4 - - [15/Aug/2026:20:03:11 +0800] &quot;POST /api/order HTTP/1.1&quot; 502 157</span></span>
<span class="line"><span>  upstream: &quot;127.0.0.1:8081, 127.0.0.1:8082&quot; status: &quot;502, 502&quot; rt: &quot;0.001, 0.002&quot;</span></span></code></pre></div><p>一行日志同时记录<strong>试过哪些实例、各拿到什么状态、各花多久</strong>——上面这行说的是：两台都被试了、都立刻失败（rt 毫秒级），这是连接被拒的典型形态。配合 error.log 里的系统级 errno，决策树如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>线上 5xx，先看是什么错</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ 502（bad gateway：上游没应答或应答不合法）</span></span>
<span class="line"><span>│   ├─ error.log 有 &quot;Connection refused (111)&quot;</span></span>
<span class="line"><span>│   │    → 上游进程不在：挂了/OOM/发版窗口 → 第 7 章的分组与重试是解药</span></span>
<span class="line"><span>│   ├─ error.log 有 &quot;Connection reset by peer (104)&quot;</span></span>
<span class="line"><span>│   │    → 上游进程在但掐了连接：崩溃重启中 / 接收缓冲打爆</span></span>
<span class="line"><span>│   ├─ error.log 有 &quot;no live upstreams&quot;</span></span>
<span class="line"><span>│   │    → 组里全灭或全被 max_fails 拉黑 → 先恢复实例，再查为什么集体死</span></span>
<span class="line"><span>│   └─ 502 但上游日志完全没收到请求</span></span>
<span class="line"><span>│        → 连接根本没建立成功：防火墙/安全组/端口配错（proxy_pass 指错了门牌）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ 504（gateway timeout：上游应了但太慢）</span></span>
<span class="line"><span>│   ├─ error.log 有 &quot;upstream timed out (110)&quot;</span></span>
<span class="line"><span>│   │    → 上端真慢：慢查询/下游依赖卡死 → 加大 proxy_read_timeout 只是止痛，</span></span>
<span class="line"><span>│      根治要么治上游，要么第 8、9 章的压缩缓存减负</span></span>
<span class="line"><span>│   └─ 只在高峰出现 → 容量问题：连接池打满/线程池排队 → 上游扩容（第 7 章的组随时可加实例）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└─ 504 且 upstream rt 接近精确的整数十秒</span></span>
<span class="line"><span>     → 撞的是网关自己的默认超时（60s）：确认谁设的、该不该这么长</span></span></code></pre></div><p>三个提速技巧。<strong>绕过网关直敲上游</strong>：<code>curl -H &#39;Host: api.internal&#39; http://127.0.0.1:8081/health</code>——通，则问题在网关配置；不通，问题在上游本身，把「三方对峙」立刻变回两方。<strong>用第 6 章的头知识定位链路</strong>：让上游日志打印 <code>X-Forwarded-For</code>，流量有没有穿过网关、穿的哪一层，一目了然。<strong>用第 9 章的缓存知识解释&quot;幽灵故障&quot;</strong>：上游明明恢复了，部分用户还在报错——先怀疑客户端/CDN 的强缓存，再怀疑代码。</p><p>前端在这个流程里不是旁观者：你是<strong>第一 noticing 的人</strong>，报障时带上三个信息，能把定位时间从两小时压到十分钟——状态码（502 还是 504）、时间点（精确到分钟，运维好对日志）、范围（全量用户还是部分、哪些接口）。本章开头那场事故，最后复盘的结论就是：如果前端第一分钟报了「20:03 起订单接口 502」，运维 20:04 就能 grep 到那串 <code>Connection refused</code>。</p><h2 id="延伸阅读-从-mini-到官方文档" tabindex="-1">延伸阅读：从 mini 到官方文档 <a class="header-anchor" href="#延伸阅读-从-mini-到官方文档" aria-label="Permalink to &quot;延伸阅读：从 mini 到官方文档&quot;">​</a></h2><p>全书按特性走，官方文档按模块组织，对照入口如下：</p><ul><li>静态与路由：<code>ngx_http_core_module</code>（root/alias/try_files/location）</li><li>代理：<code>ngx_http_proxy_module</code>（proxy_pass/proxy_set_header/proxy_next_upstream）</li><li>压缩与缓存：<code>ngx_http_gzip_module</code>、<code>ngx_http_headers_module</code>（expires/add_header）</li><li>跨域：没有专门的 CORS 模块——就是 headers 模块的 add_header 组合，本章与第 10 章的配置即全部</li><li>日志：<code>ngx_http_log_module</code>（log_format 的全部变量，排障字段的出处）</li></ul><p>读官方文档前你已经有的优势：每个指令你都用 TypeScript 写过一遍行为等价物，文档里的每句&quot;注意事项&quot;你都能翻译成「哦，那个 if 分支」。</p><hr><p><strong>全书终点</strong>：你拥有一个 642 行、55 个测试全绿的 mini-nginx——静态服务、location 匹配、SPA 回退、反向代理、头透传、WebSocket、负载均衡、gzip、缓存、CORS 十大前端场景各成一块；以及一张知道自己在哪、缺什么差异地图。下次线上 502，希望你是那个说「先看 upstream 字段」的人。</p>`,21)])])}const h=n(d,[["render",o]]);export{u as __pageData,h as default};
